--
-- Triggers `tblTourSales_Bookings`
--
DELIMITER $$
CREATE TRIGGER `trgSalesBooking` BEFORE INSERT ON `tblTourSales_Bookings` FOR EACH ROW SET 
NEW.bookingNumber = 
if(
exists (select 1 from tblTourSales_Bookings WHERE year(tblTourSales_Bookings.bookedAt)=year(NEW.bookedAt))
,
(
SELECT concat(tblDoc_DocumentPrefixes.documentPrefix,'-',tblDoc_DocumentPrefixes.companyPrefix,'-',year(tblTourSales_Bookings.bookedAt)-2000,'-',
substr(1000000+MAX(abs(substr(tblTourSales_Bookings.bookingNumber,10,6)))+1,2,6) 
) 
FROM tblTourSales_Bookings 
left join tblDoc_DocumentPrefixes on (tblDoc_DocumentPrefixes.siteID=NEW.siteID and tblDoc_DocumentPrefixes.documentType='isBooking')
WHERE year(tblTourSales_Bookings.bookedAt)=year(NEW.bookedAt)
limit 0,1
)
,
(
SELECT concat(tblDoc_DocumentPrefixes.documentPrefix,'-',tblDoc_DocumentPrefixes.companyPrefix,'-',year(NEW.bookedAt)-2000,'-000001')
FROM tblDoc_DocumentPrefixes 
WHERE tblDoc_DocumentPrefixes.siteID=NEW.siteID and tblDoc_DocumentPrefixes.documentType='isBooking'
limit 0,1
)
)
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trgSalesBooking_delete` AFTER DELETE ON `tblTourSales_Bookings` FOR EACH ROW begin
    delete from tblTourSales_ggInvoiceSubs where tblTourSales_ggInvoiceSubs.bookingID=old.bookingID;
    delete from tblTourSales_BookingGuests where tblTourSales_BookingGuests.bookingID=old.bookingID;
  end
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trgTourSales_Bookings_insert` BEFORE INSERT ON `tblTourSales_Bookings` FOR EACH ROW IF (NEW.companyID=2) THEN
        SET NEW.company1ID = 11;
  END IF
$$
DELIMITER ;

