DROP TABLE IF EXISTS `qryAccAcc_GLAccounts1`;

CREATE ALGORITHM=UNDEFINED DEFINER=`mitja`@`%` SQL SECURITY DEFINER VIEW `qryAccAcc_GLAccounts1`  AS SELECT `tblAccAcc_GLAccounts`.`GLAccountID` AS `GLAccountID`, concat(`tblAccAcc_OfficialAccounts_2`.`officialAccountNumber`,' - ',`tblAccAcc_OfficialAccounts_2`.`officialAccountName`) AS `L1`, concat(`tblAccAcc_OfficialAccounts_1`.`officialAccountNumber`,' - ',`tblAccAcc_OfficialAccounts_1`.`officialAccountName`) AS `L2`, concat(`tblAccAcc_OfficialAccounts`.`officialAccountNumber`,' - ',`tblAccAcc_OfficialAccounts`.`officialAccountName`) AS `L3`, `tblAccAcc_GLAccounts`.`glAccountNumber` AS `glAccountNumber`, concat(insert(`tblAccAcc_GLAccounts`.`glAccountNumber`,4,0,'-'),' ',`tblAccAcc_GLAccounts`.`glAccountName`) AS `GLAccName`, `tblAccAcc_GLAccounts`.`showBP` AS `showBP`, `tblAccAcc_GLAccounts`.`considerPartner` AS `considerPartner`, `tblAccAcc_OfficialAccounts_1`.`excludeFromFS` AS `excludeFromFS`, `tblAccAcc_GLAccounts`.`isPRAccount` AS `isPRAccount`, `tblAccAcc_OfficialAccounts_2`.`isBSAccount` AS `isBSAccount`, `tblAccAcc_OfficialAccounts`.`balanceSign` AS `balanceSign` FROM (((`tblAccAcc_GLAccounts` join `tblAccAcc_OfficialAccounts` on(`tblAccAcc_GLAccounts`.`officialAccountID` = `tblAccAcc_OfficialAccounts`.`officialAccountID`)) join `tblAccAcc_OfficialAccounts` `tblAccAcc_OfficialAccounts_1` on(`tblAccAcc_OfficialAccounts`.`levelupOfficialAccountID` = `tblAccAcc_OfficialAccounts_1`.`officialAccountID`)) join `tblAccAcc_OfficialAccounts` `tblAccAcc_OfficialAccounts_2` on(`tblAccAcc_OfficialAccounts_1`.`levelupOfficialAccountID` = `tblAccAcc_OfficialAccounts_2`.`officialAccountID`))  ;

