Acceptances`.`acceptanceID` AS `docID`,`tblDocGoods_Acceptances`.`createdAt` AS `dt`,13 AS `documentTypeID` from `tblDocGoods_Acceptances` union select `tblDocGoods_WriteOffs`.`companyID` AS `companyID`,`tblDocGoods_WriteOffs`.`writeOffID` AS `docID`,`tblDocGoods_WriteOffs`.`createdAt` AS `dt`,14 AS `documentTypeID` from `tblDocGoods_WriteOffs` union select `tblAccPmt_PaymentJournalNames`.`companyID` AS `companyID`,`tblAccPmt_PaymentTransactions`.`paymentTransactionID` AS `docID`,`tblAccPmt_PaymentJournals`.`createdAt` AS `dt`,15 AS `documentTypeID` from ((`tblAccPmt_PaymentJournalNames` join `tblAccPmt_PaymentJournals` on(`tblAccPmt_PaymentJournalNames`.`paymentJournalNameID` = `tblAccPmt_PaymentJournals`.`paymentJournalNameID`)) join `tblAccPmt_PaymentTransactions` on(`tblAccPmt_PaymentJournals`.`paymentJournalID` = `tblAccPmt_PaymentTransactions`.`paymentJournalID`)) union select `tblAccPmt_PaymentJournalNames`.`companyID` AS `companyID`,`tblAccPmt_PaymentTransactions`.`paymentTransactionID` AS `docID`,`tblAccPmt_PaymentJournals`.`createdAt` AS `dt`,16 AS `documentTypeID` from ((`tblAccPmt_PaymentJournalNames` join `tblAccPmt_PaymentJournals` on(`tblAccPmt_PaymentJournalNames`.`paymentJournalNameID` = `tblAccPmt_PaymentJournals`.`paymentJournalNameID`)) join `tblAccPmt_PaymentTransactions` on(`tblAccPmt_PaymentJournals`.`paymentJournalID` = `tblAccPmt_PaymentTransactions`.`paymentJournalID`)) where `tblAccPmt_PaymentTransactions`.`ptAmount` < 0 union select `tblAccVat_DDVO`.`companyID` AS `companyID`,`tblAccVat_DDVO`.`ddvoID` AS `docID`,`tblAccFP_FiscalMonths`.`monthLastDate` + interval 20 day AS `dt`,17 AS `documentTypeID` from (`tblAccVat_DDVO` join `tblAccFP_FiscalMonths` on(`tblAccVat_DDVO`.`fiscalMonth2ID` = `tblAccFP_FiscalMonths`.`fiscalMonthID`)) union select `tblPtr_PartnersCmpys`.`companyID` AS `companyID`,`tblPtr_PartnersCmpys`.`partnerCmpyID` AS `docID`,`tblPtr_PartnersCmpys`.`createdAt` AS `dt`,21 AS `documentTypeID` from `tblPtr_PartnersCmpys`  ;

