DROP TABLE IF EXISTS `qryEmpWC_jobEnd1sub`;

CREATE ALGORITHM=UNDEFINED DEFINER=`mitja`@`%` SQL SECURITY DEFINER VIEW `qryEmpWC_jobEnd1sub`  AS SELECT `SUB`.`employmentID` AS `employmentID`, sum(timestampdiff(SECOND,`SUB`.`jobStart`,`SUB`.`jobEnd`) / 3600) AS `workH`, 0 AS `absenceH` FROM `tblEmpTime_DailyTimeclock` AS `SUB` WHERE month(`SUB`.`jobStart`) = 10 AND year(`SUB`.`jobStart`) = 2025 AND `SUB`.`deletedAt` is null GROUP BY `SUB`.`employmentID` union select `tblEmpTime_Absence`.`employmentID` AS `employmentID`,0 AS `workH`,sum(`tblEmpTime_Absence`.`absenceQty`) AS `absenceH` from (((`tblAccFP_FiscalMonths` join `tblEmpTime_Absence` on(`tblAccFP_FiscalMonths`.`fiscalMonthID` = `tblEmpTime_Absence`.`fiscalMonthID`)) join `tblEmp_Jobs` on(`tblEmpTime_Absence`.`jobID` = `tblEmp_Jobs`.`jobID`)) join `tblEmpWC_WageTypeSubSubs` on(`tblEmp_Jobs`.`wageTypeSubSubID` = `tblEmpWC_WageTypeSubSubs`.`wageTypeSubSubID`)) where `tblAccFP_FiscalMonths`.`fiscalMonth` = 10 and `tblAccFP_FiscalMonths`.`fiscalYear` = 2025 and `tblEmpTime_Absence`.`jobID` is not null and `tblEmpWC_WageTypeSubSubs`.`REKaHours` = 1 group by `tblEmpTime_Absence`.`employmentID`  ;

-- --------------------------------------------------------

--
-- Structure for view `qryEmpWC_NoOfEmpWorkingDays_Absence`
--
DROP TABLE IF EXISTS `qryEmpWC_NoOfEmpWorkingDays_Absence`;

CREATE ALGORITHM=UNDEFINED DEFINER=`mitja`@`%` SQL SECURITY DEFINER VIEW `qryEmpWC_NoOfEmpWorkingDays_Absence`  AS SELECT `tblEmpWC_WageCalculationSubs`.`wageCalculationID` AS `wageCalculationID`, `tblEmpWC_WageCalculationSubs`.`wageCalculationSubID` AS `wageCalculationSubID`, round(sum(`tblEmpTime_Absence`.`absenceQty`),0) AS `empAbsH`, round(sum(`tblEmpTime_Absence`.`absenceQty`) / 8,0) AS `empAbsD` FROM (((`tblEmpWC_WageCalculationSubs` join `tblEmpWC_WageCalculationSubSubs` on(`tblEmpWC_WageCalculationSubs`.`wageCalculationSubID` = `tblEmpWC_WageCalculationSubSubs`.`wageCalculationSubID`)) join `tblEmpTime_Absence` on(`tblEmpWC_WageCalculationSubSubs`.`employmentID` = `tblEmpTime_Absence`.`employmentID`)) join `tblEmpWC_WageCalculations` on(`tblEmpWC_WageCalculations`.`fiscalMonthID` = `tblEmpTime_Absence`.`fiscalMonthID` and `tblEmpWC_WageCalculationSubs`.`wageCalculationID` = `tblEmpWC_WageCalculations`.`wageCalculationID`)) GROUP BY `tblEmpWC_WageCalculationSubs`.`wageCalculationSubID``wageCalculationSubID`  ;

-- --------------------------------------------------------

--
-- Structure for view `qryEmpWC_NoOfEmpWorkingDays_notTCUsers`
--
DROP TABLE IF EXISTS `qryEmpWC_NoOfEmpWorkingDays_notTCUsers`;

CREATE ALGORITHM=UNDEFINED DEFINER=`mitja`@`%` SQL SECURITY DEFINER VIEW `qryEmpWC_NoOfEmpWorkingDays_notTCUsers`  AS SELECT `qryEmpWC_wcData`.`wageCalculationSubID` AS `wageCalculationSubID`, round((`qryEmpWC_wcData`.`D2` - `qryEmpWC_wcData`.`D1` + 1) / (`qryEmpWC_wcData`.`monthLastDate` - `qryEmpWC_wcData`.`monthFirstDate` + 1) * `qryEmpWC_wcData`.`mnthHours` / 8,0) * 8 - if(`qryEmpWC_NoOfEmpWorkingDays_Absence`.`empAbsH` is null,0,`qryEmpWC_NoOfEmpWorkingDays_Absence`.`empAbsH`) AS `workH`, if(`qryEmpWC_NoOfEmpWorkingDays_Absence`.`empAbsH` is null,0,`qryEmpWC_NoOfEmpWorkingDays_Absence`.`empAbsH`) AS `absH`, round(`qryEmpWC_wcData`.`monthlyEarning` / `qryEmpWC_wcData`.`mnthHours` * (round((`qryEmpWC_wcData`.`D2` - `qryEmpWC_wcData`.`D1` + 1) / (`qryEmpWC_wcData`.`monthLastDate` - `qryEmpWC_wcData`.`monthFirstDate` + 1) * `qryEmpWC_wcData`.`mnthHours` / 8,0) * 8 - if(`qryEmpWC_NoOfEmpWorkingDays_Absence`.`empAbsH` is null,0,`qryEmpWC_NoOfEmpWorkingDays_Absence`.`empAbsH`)),0) AS `workEarning` FROM (`qryEmpWC_wcData` left join `qryEmpWC_NoOfEmpWorkingDays_Absence` on(`qryEmpWC_wcData`.`wageCalculationSubID` = `qryEmpWC_NoOfEmpWorkingDays_Absence`.`wageCalculationSubID`)) WHERE `qryEmpWC_wcData`.`usesTimeclock` = 00  ;

