CREATE ALGORITHM=UNDEFINED DEFINER=`mitja`@`%` SQL SECURITY DEFINER VIEW `qryEmpWC_NoOfEmpWorkingDays_Presence`  AS SELECT `qryEmpWC_NoOfEmpWorkingDays_Presence_TCUsers`.`wageCalculationSubID` AS `wageCalculationSubID`, round(`qryEmpWC_NoOfEmpWorkingDays_Presence_TCUsers`.`noOfWD`,0) AS `noOfWD` FROM `qryEmpWC_NoOfEmpWorkingDays_Presence_TCUsers` union select `qryEmpWC_NoOfEmpWorkingDays_Presence_notTCUsers`.`wageCalculationSubID` AS `wageCalculationSubID`,round(`qryEmpWC_NoOfEmpWorkingDays_Presence_notTCUsers`.`workH` / 8,0) AS `noOfWD` from `qryEmpWC_NoOfEmpWorkingDays_Presence_notTCUsers`  ;

