--
-- Structure for view `qryEmpWC_rptYearlyPayrolls`
--
DROP TABLE IF EXISTS `qryEmpWC_rptYearlyPayrolls`;

CREATE ALGORITHM=UNDEFINED DEFINER=`mitja`@`%` SQL SECURITY DEFINER VIEW `qryEmpWC_rptYearlyPayrolls`  AS SELECT `tblCmpy_Companies`.`cmpyName` AS `cmpyName`, `tblCmpy_Companies`.`cmpyTaxNumber` AS `cmpyTaxNumber`, `tblEmpWC_WageCalculationSubs`.`employeeID` AS `employeeID`, `tblPtr_Partners`.`taxNumber` AS `taxNumber`, `tblPtr_Partners`.`socialNumber` AS `socialNumber`, concat_ws(' ',`tblPtr_Partners`.`name1`,`tblPtr_Partners`.`name2`) AS `empName`, `tblEmpWC_Payouts_PayrollCalculations`.`payrollName` AS `payrollName`, `tblEmpWC_Payouts_PayrollCalculations`.`payDate` AS `payDate`, round(100 * `qryEmpWC_rptYearlyPayrolls_Payrolls`.`grossEarning`,0) AS `grossEarning`, round(100 * `qryEmpWC_rptYearlyPayrolls_Taxes`.`personalIncomeTax`,0) AS `personalIncomeTax`, round(100 * `qryEmpWC_rptYearlyPayrolls_Taxes`.`contributions`,0) AS `contributions`, round(100 * (`qryEmpWC_rptYearlyPayrolls_Payrolls`.`grossEarning` - `qryEmpWC_rptYearlyPayrolls_Taxes`.`personalIncomeTax` - `qryEmpWC_rptYearlyPayrolls_Taxes`.`contributions`),0) AS `netEarning`, year(`tblEmpWC_Payouts_PayrollCalculations`.`payDate`) AS `yr`, `tblAccFP_FiscalMonths`.`fiscalYear` AS `fiscalYear`, `tblEmpWC_WageCalculations`.`companyID` AS `companyID` FROM ((((((`tblEmpWC_WageCalculationSubs` join `tblEmpWC_WageCalculations` on(`tblEmpWC_WageCalculationSubs`.`wageCalculationID` = `tblEmpWC_WageCalculations`.`wageCalculationID`)) join ((`qryEmpWC_rptYearlyPayrolls_Payrolls` left join `qryEmpWC_rptYearlyPayrolls_Taxes` on(`qryEmpWC_rptYearlyPayrolls_Payrolls`.`payrollID` = `qryEmpWC_rptYearlyPayrolls_Taxes`.`payrollID`)) join `tblEmpWC_Payouts_Payrolls` on(`qryEmpWC_rptYearlyPayrolls_Payrolls`.`payrollID` = `tblEmpWC_Payouts_Payrolls`.`payrollID`)) on(`tblEmpWC_WageCalculationSubs`.`wageCalculationSubID` = `tblEmpWC_Payouts_Payrolls`.`wageCalculationSubID`)) join `tblEmpWC_Payouts_PayrollCalculations` on(`tblEmpWC_Payouts_PayrollCalculations`.`wageCalculationID` = `tblEmpWC_WageCalculations`.`wageCalculationID` and `tblEmpWC_Payouts_Payrolls`.`payrollCalculationID` = `tblEmpWC_Payouts_PayrollCalculations`.`payrollCalculationID`)) join `tblCmpy_Companies` on(`tblEmpWC_WageCalculations`.`companyID` = `tblCmpy_Companies`.`companyID`)) join `tblPtr_Partners` on(`tblEmpWC_WageCalculationSubs`.`employeeID` = `tblPtr_Partners`.`partnerID`)) join `tblAccFP_FiscalMonths` on(`tblEmpWC_WageCalculations`.`fiscalMonthID` = `tblAccFP_FiscalMonths`.`fiscalMonthID`))  ;

-- --------------------------------------------------------

--
-- Structure for view `qryEmpWC_rptYearlyPayrolls_Payrolls`
