DROP TABLE IF EXISTS `qryEmpWC_rptYearlyPayrolls_Payrolls`;

CREATE ALGORITHM=UNDEFINED DEFINER=`mitja`@`%` SQL SECURITY DEFINER VIEW `qryEmpWC_rptYearlyPayrolls_Payrolls`  AS SELECT `tblEmpWC_Payouts_Payrolls`.`payrollID` AS `payrollID`, sum(`tblEmpWC_Payouts_PayrollEarnings`.`earningQty` * `tblEmpWC_Payouts_PayrollEarnings`.`earningRate` * `tblEmpWC_Payouts_PayrollEarnings`.`multiplier`) AS `grossEarning` FROM (`tblEmpWC_Payouts_Payrolls` join (`tblEmpWC_Payouts_PayrollEarnings` join `tblEmpWC_WageTypeSubSubs` on(`tblEmpWC_Payouts_PayrollEarnings`.`wageTypeSubSubID` = `tblEmpWC_WageTypeSubSubs`.`wageTypeSubSubID`)) on(`tblEmpWC_Payouts_Payrolls`.`payrollID` = `tblEmpWC_Payouts_PayrollEarnings`.`payrollID`)) WHERE `tblEmpWC_WageTypeSubSubs`.`wageType` <> 'isTransport' AND `tblEmpWC_WageTypeSubSubs`.`wageType` <> 'isFood' GROUP BY `tblEmpWC_Payouts_Payrolls`.`payrollID``payrollID`  ;

-- --------------------------------------------------------

--
-- Structure for view `qryEmpWC_rptYearlyPayrolls_Taxes`
