DROP TABLE IF EXISTS `qryEmpWC_rptYearlyPayrolls_Taxes`;

CREATE ALGORITHM=UNDEFINED DEFINER=`mitja`@`%` SQL SECURITY DEFINER VIEW `qryEmpWC_rptYearlyPayrolls_Taxes`  AS SELECT `tblEmpWC_Payouts_Payrolls`.`payrollID` AS `payrollID`, sum(if(`tblEmpWC_WageTaxes`.`isPersonalIncomeTax` = 1,`tblEmpWC_Payouts_PayrollTaxes`.`taxAmount`,0)) AS `personalIncomeTax`, sum(if(`tblEmpWC_WageTaxes`.`isPersonalIncomeTax` = 0,`tblEmpWC_Payouts_PayrollTaxes`.`taxAmount`,0)) AS `contributions` FROM (`tblEmpWC_Payouts_Payrolls` join (`tblEmpWC_Payouts_PayrollTaxes` join `tblEmpWC_WageTaxes` on(`tblEmpWC_Payouts_PayrollTaxes`.`wageTaxID` = `tblEmpWC_WageTaxes`.`wageTaxID`)) on(`tblEmpWC_Payouts_Payrolls`.`payrollID` = `tblEmpWC_Payouts_PayrollTaxes`.`payrollID`)) WHERE `tblEmpWC_WageTaxes`.`isEmployeeObligation` = 1 GROUP BY `tblEmpWC_Payouts_Payrolls`.`payrollID``payrollID`  ;

