--
-- Triggers `tblTourB_BundleUnits`
--
DELIMITER $$
CREATE TRIGGER `tblTourB_BundleUnits_delete` AFTER DELETE ON `tblTourB_BundleUnits` FOR EACH ROW delete from tblTourB_BundleProducts 
  where tblTourB_BundleProducts.bundleID=old.bundleID
  and tblTourB_BundleProducts.bundleUnitID=old.bundleUnitID
  and tblTourB_BundleProducts.bundleUnitProduct=1
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `tblTourB_BundleUnits_insert` AFTER INSERT ON `tblTourB_BundleUnits` FOR EACH ROW insert ignore into tblTourB_BundleProducts (productID,bundleID,bundleUnitID,bundleUnitProduct)
  select 0,tblTourB_BundleUnits.bundleID, tblTourB_BundleUnits.bundleUnitID,1 
  from tblTourB_BundleUnits 
  where tblTourB_BundleUnits.bundleUnitID=new.bundleUnitID
$$
DELIMITER ;

